window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8ab59f3b0f1d4f0b"]={"versions": [{"id": "FIG-8ab59f3b0f1d4f0b", "releases": ["R4.0.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-M1-Instanzmodell (UML-Objekt- bzw. Instanzdiagramm) zur Veranschaulichung der Metamodell-Konzepte aus dem Generic Structure Template (<code>AUTOSAR_TPS_GenericStructureTemplate</code>). Das Diagramm illustriert die Semantik und Deklaration einer Instanzreferenz (<code>PortInCompositionInstanceRef</code>) auf M1-Ebene, mit der ein konkreter Port innerhalb einer hierarchischen Komponentenarchitektur eindeutig referenziert wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>«compositionType» PowerWindowType</code>: Übergeordnete Composition-Komponente, die als Wurzel- und Kapselelement fungiert.\n</li><li><code>«ComponentPrototype» leftController:WindowControllerType</code>: Komponenten-Prototyp innerhalb von <code>PowerWindowType</code> mit dem Port <code>ctrl</code>.\n</li><li><code>«ComponentPrototype» rightController:WindowControllerType</code>: Komponenten-Prototyp innerhalb von <code>PowerWindowType</code> mit dem Port <code>ctrl</code>.\n</li><li><code>«ComponentPrototype» mainController:MainControllerType</code>: Zentraler Steuerungs-Prototyp mit den Ports <code>leftCtrl</code> und <code>rightCtrl</code>. Die Ports <code>leftCtrl</code> und <code>rightCtrl</code> sind jeweils über Assembly-Konnektoren mit den Ports <code>ctrl</code> der entsprechenden WindowController-Prototypen verbunden.\n</li><li><code>«ApplicationComponentType» WindowControllerType</code>: Wiederverwendbarer Software-Komponententyp mit dem Schnittstellen-Port <code>ctrl</code>.\n</li><li><code>«PortInCompositionInstanceRef» ctrlInRightControllerInPowerWindowType</code>: M1-Instanzreferenz-Element mit drei gerichteten Assoziations-/Navigationsrollen (gestrichelte Pfeile):\n<ul class=\"fig-list\"><li><code>+base</code>: verweist auf den Wurzelkontext <code>PowerWindowType</code>.\n</li><li><code>+context</code>: verweist auf den Pfad-/Instanzkontext <code>rightController:WindowControllerType</code> (bzw. dessen Port).\n</li><li><code>+target</code>: verweist auf das finale Ziel-Portelement <code>ctrl</code> am Komponententyp <code>WindowControllerType</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Strukturierungs- und Navigationsbeziehung dar. Es beschreibt keinen dynamischen Laufzeit- oder Sequenzablauf, sondern definiert den statischen M1-Pfad zur eindeutigen Auflösung einer M0-Laufzeitinstanz: Ausgehend von der Basis (<code>+base: PowerWindowType</code>) navigiert die Referenz über den Instanzkontext (<code>+context: rightController</code>) zum Ziel-Port (<code>+target: ctrl</code> des <code>WindowControllerType</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptionelles Erläuterungsbeispiel für Entwickler von AUTOSAR-Autorensystemen und Modellierungswerkzeugen zur korrekten Instanziierung konkreter Subklassen von <code>AtpInstanceRef</code>. Die Rollen <code>+base</code>, <code>+context</code> und <code>+target</code> stellen sicher, dass Instanzen innerhalb tief geschachtelter Kompositionsbäume ohne Mehrdeutigkeiten adressiert werden können, auch wenn ein <code>ApplicationComponentType</code> mehrfach instanziiert wird.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-eadfe670fb2dbbee", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-M1-Instanzmodell (UML-Objekt- bzw. Instanzdiagramm) zur Veranschaulichung der Metamodell-Konzepte aus dem Generic Structure Template (<code>AUTOSAR_TPS_GenericStructureTemplate</code>). Das Diagramm illustriert die Semantik und Deklaration einer Instanzreferenz (<code>PortInCompositionInstanceRef</code>) auf M1-Ebene, mit der ein konkreter Port innerhalb einer hierarchischen Komponentenarchitektur eindeutig referenziert wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>«compositionType» PowerWindowType</code>: Übergeordnete Composition-Komponente, die als Wurzel- und Kapselelement fungiert.\n</li><li><code>«ComponentPrototype» leftController:WindowControllerType</code>: Komponenten-Prototyp innerhalb von <code>PowerWindowType</code> mit dem Port <code>ctrl</code>.\n</li><li><code>«ComponentPrototype» rightController:WindowControllerType</code>: Komponenten-Prototyp innerhalb von <code>PowerWindowType</code> mit dem Port <code>ctrl</code>.\n</li><li><code>«ComponentPrototype» mainController:MainControllerType</code>: Zentraler Steuerungs-Prototyp mit den Ports <code>leftCtrl</code> und <code>rightCtrl</code>. Die Ports <code>leftCtrl</code> und <code>rightCtrl</code> sind jeweils über Assembly-Konnektoren mit den Ports <code>ctrl</code> der entsprechenden WindowController-Prototypen verbunden.\n</li><li><code>«ApplicationComponentType» WindowControllerType</code>: Wiederverwendbarer Software-Komponententyp mit dem Schnittstellen-Port <code>ctrl</code>.\n</li><li><code>«PortInCompositionInstanceRef» ctrlInRightControllerInPowerWindowType</code>: M1-Instanzreferenz-Element mit drei gerichteten Assoziations-/Navigationsrollen (gestrichelte Pfeile):\n<ul class=\"fig-list\"><li><code>+base</code>: verweist auf den Wurzelkontext <code>PowerWindowType</code>.\n</li><li><code>+context</code>: verweist auf den Pfad-/Instanzkontext <code>rightController:WindowControllerType</code> (bzw. dessen Port).\n</li><li><code>+target</code>: verweist auf das finale Ziel-Portelement <code>ctrl</code> am Komponententyp <code>WindowControllerType</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Strukturierungs- und Navigationsbeziehung dar. Es beschreibt keinen dynamischen Laufzeit- oder Sequenzablauf, sondern definiert den statischen M1-Pfad zur eindeutigen Auflösung einer M0-Laufzeitinstanz: Ausgehend von der Basis (<code>+base: PowerWindowType</code>) navigiert die Referenz über den Instanzkontext (<code>+context: rightController</code>) zum Ziel-Port (<code>+target: ctrl</code> des <code>WindowControllerType</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptionelles Erläuterungsbeispiel für Entwickler von AUTOSAR-Autorensystemen und Modellierungswerkzeugen zur korrekten Instanziierung konkreter Subklassen von <code>AtpInstanceRef</code>. Die Rollen <code>+base</code>, <code>+context</code> und <code>+target</code> stellen sicher, dass Instanzen innerhalb tief geschachtelter Kompositionsbäume ohne Mehrdeutigkeiten adressiert werden können, auch wenn ein <code>ApplicationComponentType</code> mehrfach instanziiert wird.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c2f9d773c124ac7c", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-M1-Instanzmodell (UML-Objekt- bzw. Instanzdiagramm) zur Veranschaulichung der Metamodell-Konzepte aus dem Generic Structure Template (<code>AUTOSAR_TPS_GenericStructureTemplate</code>). Das Diagramm illustriert die Semantik und Deklaration einer Instanzreferenz (<code>PortInCompositionInstanceRef</code>) auf M1-Ebene, mit der ein konkreter Port innerhalb einer hierarchischen Komponentenarchitektur eindeutig referenziert wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>«compositionType» PowerWindowType</code>: Übergeordnete Composition-Komponente, die als Wurzel- und Kapselelement fungiert.\n</li><li><code>«ComponentPrototype» leftController:WindowControllerType</code>: Komponenten-Prototyp innerhalb von <code>PowerWindowType</code> mit dem Port <code>ctrl</code>.\n</li><li><code>«ComponentPrototype» rightController:WindowControllerType</code>: Komponenten-Prototyp innerhalb von <code>PowerWindowType</code> mit dem Port <code>ctrl</code>.\n</li><li><code>«ComponentPrototype» mainController:MainControllerType</code>: Zentraler Steuerungs-Prototyp mit den Ports <code>leftCtrl</code> und <code>rightCtrl</code>. Die Ports <code>leftCtrl</code> und <code>rightCtrl</code> sind jeweils über Assembly-Konnektoren mit den Ports <code>ctrl</code> der entsprechenden WindowController-Prototypen verbunden.\n</li><li><code>«ApplicationComponentType» WindowControllerType</code>: Wiederverwendbarer Software-Komponententyp mit dem Schnittstellen-Port <code>ctrl</code>.\n</li><li><code>«PortInCompositionInstanceRef» ctrlInRightControllerInPowerWindowType</code>: M1-Instanzreferenz-Element mit drei gerichteten Assoziations-/Navigationsrollen (gestrichelte Pfeile):\n<ul class=\"fig-list\"><li><code>+base</code>: verweist auf den Wurzelkontext <code>PowerWindowType</code>.\n</li><li><code>+context</code>: verweist auf den Pfad-/Instanzkontext <code>rightController:WindowControllerType</code> (bzw. dessen Port).\n</li><li><code>+target</code>: verweist auf das finale Ziel-Portelement <code>ctrl</code> am Komponententyp <code>WindowControllerType</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Strukturierungs- und Navigationsbeziehung dar. Es beschreibt keinen dynamischen Laufzeit- oder Sequenzablauf, sondern definiert den statischen M1-Pfad zur eindeutigen Auflösung einer M0-Laufzeitinstanz: Ausgehend von der Basis (<code>+base: PowerWindowType</code>) navigiert die Referenz über den Instanzkontext (<code>+context: rightController</code>) zum Ziel-Port (<code>+target: ctrl</code> des <code>WindowControllerType</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptionelles Erläuterungsbeispiel für Entwickler von AUTOSAR-Autorensystemen und Modellierungswerkzeugen zur korrekten Instanziierung konkreter Subklassen von <code>AtpInstanceRef</code>. Die Rollen <code>+base</code>, <code>+context</code> und <code>+target</code> stellen sicher, dass Instanzen innerhalb tief geschachtelter Kompositionsbäume ohne Mehrdeutigkeiten adressiert werden können, auch wenn ein <code>ApplicationComponentType</code> mehrfach instanziiert wird.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3017782d5ff0952b", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-M1-Instanzmodell (UML-Objekt- bzw. Instanzdiagramm) zur Veranschaulichung der Metamodell-Konzepte aus dem Generic Structure Template (<code>AUTOSAR_TPS_GenericStructureTemplate</code>). Das Diagramm illustriert die Semantik und Deklaration einer Instanzreferenz (<code>PortInCompositionInstanceRef</code>) auf M1-Ebene, mit der ein konkreter Port innerhalb einer hierarchischen Komponentenarchitektur eindeutig referenziert wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>«compositionType» PowerWindowType</code>: Übergeordnete Composition-Komponente, die als Wurzel- und Kapselelement fungiert.\n</li><li><code>«ComponentPrototype» leftController:WindowControllerType</code>: Komponenten-Prototyp innerhalb von <code>PowerWindowType</code> mit dem Port <code>ctrl</code>.\n</li><li><code>«ComponentPrototype» rightController:WindowControllerType</code>: Komponenten-Prototyp innerhalb von <code>PowerWindowType</code> mit dem Port <code>ctrl</code>.\n</li><li><code>«ComponentPrototype» mainController:MainControllerType</code>: Zentraler Steuerungs-Prototyp mit den Ports <code>leftCtrl</code> und <code>rightCtrl</code>. Die Ports <code>leftCtrl</code> und <code>rightCtrl</code> sind jeweils über Assembly-Konnektoren mit den Ports <code>ctrl</code> der entsprechenden WindowController-Prototypen verbunden.\n</li><li><code>«ApplicationComponentType» WindowControllerType</code>: Wiederverwendbarer Software-Komponententyp mit dem Schnittstellen-Port <code>ctrl</code>.\n</li><li><code>«PortInCompositionInstanceRef» ctrlInRightControllerInPowerWindowType</code>: M1-Instanzreferenz-Element mit drei gerichteten Assoziations-/Navigationsrollen (gestrichelte Pfeile):\n<ul class=\"fig-list\"><li><code>+base</code>: verweist auf den Wurzelkontext <code>PowerWindowType</code>.\n</li><li><code>+context</code>: verweist auf den Pfad-/Instanzkontext <code>rightController:WindowControllerType</code> (bzw. dessen Port).\n</li><li><code>+target</code>: verweist auf das finale Ziel-Portelement <code>ctrl</code> am Komponententyp <code>WindowControllerType</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Strukturierungs- und Navigationsbeziehung dar. Es beschreibt keinen dynamischen Laufzeit- oder Sequenzablauf, sondern definiert den statischen M1-Pfad zur eindeutigen Auflösung einer M0-Laufzeitinstanz: Ausgehend von der Basis (<code>+base: PowerWindowType</code>) navigiert die Referenz über den Instanzkontext (<code>+context: rightController</code>) zum Ziel-Port (<code>+target: ctrl</code> des <code>WindowControllerType</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptionelles Erläuterungsbeispiel für Entwickler von AUTOSAR-Autorensystemen und Modellierungswerkzeugen zur korrekten Instanziierung konkreter Subklassen von <code>AtpInstanceRef</code>. Die Rollen <code>+base</code>, <code>+context</code> und <code>+target</code> stellen sicher, dass Instanzen innerhalb tief geschachtelter Kompositionsbäume ohne Mehrdeutigkeiten adressiert werden können, auch wenn ein <code>ApplicationComponentType</code> mehrfach instanziiert wird.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8ab59f3b0f1d4f0b", "to": "FIG-eadfe670fb2dbbee", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-eadfe670fb2dbbee", "to": "FIG-c2f9d773c124ac7c", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Beim Stereotyp <code>«compositionType»</code> des Elements <code>PowerWindowType</code> entfällt die horizontale Trennlinie zwischen dem oberen Kopfbereich und dem Inhaltsbereich des umschließenden Rahmens.\n</li><li>Bei den beiden Port-Rechtecken <code>ctrl</code> (rot umrandet) an <code>leftController</code> und <code>rightController</code> wird die vertikale Ausrichtung geringfügig nach unten verschoben, sodass sie die Unterkante des jeweiligen Komponenten-Rechtecks schneiden, anstatt bündig aufzusitzen.\n</li></ul>"}, {"from": "FIG-c2f9d773c124ac7c", "to": "FIG-3017782d5ff0952b", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
